@dataclass(frozen=True, slots=True)
class TemplateSpec:
    """Description of a project template exposed to the editor integration."""

    template_id: str
    name: str
    category: str
    preview_key: str
    payload: Mapping[str, Any] = field(default_factory=dict)


DEFAULT_TEMPLATES: tuple[TemplateSpec, ...] = (
    TemplateSpec("blank", "Blank", "blank", "blank"),
    TemplateSpec("baseplate", "Baseplate", "blank", "baseplate"),
    TemplateSpec("flat_terrain", "Flat Terrain", "blank", "flat_terrain"),
    TemplateSpec("starter_scene", "Starter Scene", "gameplay", "starter_scene"),
    TemplateSpec("obby", "Obby", "gameplay", "obby"),
    TemplateSpec("village", "Village", "themed", "village"),
    TemplateSpec("castle", "Castle", "themed", "castle"),
    TemplateSpec("suburban", "Suburban", "themed", "suburban"),
    TemplateSpec("island", "Island", "themed", "island"),
    TemplateSpec("racing", "Racing", "gameplay", "racing"),
    TemplateSpec("city_block", "City Block", "themed", "city_block"),
    TemplateSpec("fps_arena", "FPS Arena", "gameplay", "fps_arena"),
)


# -----------------------------------------------------------------------------
# Theme constants
# -----------------------------------------------------------------------------

_BG_TOP = QColor("#121820")
_BG_BOTTOM = QColor("#0c1117")
_BG_GLOW = QColor(33, 49, 68, 76)
_TOPBAR_BG = QColor("#0d1218")
_SIDEBAR_TOP = QColor("#111820")
_SIDEBAR_BOTTOM = QColor("#0d1319")
_PANEL_BORDER = QColor("#252c35")
_CARD_TOP = QColor("#1a2027")
_CARD_BOTTOM = QColor("#151a20")
_CARD_BORDER = QColor("#2a313a")
_CARD_BORDER_HOVER = QColor("#3a4654")
_ACCENT = QColor("#4f8cff")
_ACCENT_BRIGHT = QColor("#67a0ff")
_TEXT = QColor("#f3f5f8")
_TEXT_MUTED = QColor("#b4bbc5")
_ICON = QColor("#a2abb6")


# -----------------------------------------------------------------------------
# Utility helpers
# -----------------------------------------------------------------------------

def _font(size: int, weight: int = QFont.Weight.Normal) -> QFont:
    font = QFont("Segoe UI")
    font.setPixelSize(size)
    font.setWeight(weight)
    font.setStyleStrategy(QFont.StyleStrategy.PreferAntialias)
    return font


def _pixmap_from_embedded(key: str) -> QPixmap:
    encoded = _EMBEDDED_PREVIEWS.get(key)
    if not encoded:
        return QPixmap()
    pixmap = QPixmap()
    pixmap.loadFromData(base64.b64decode(encoded), "JPG")
    return pixmap


def _draw_rounded_pixmap(
    painter: QPainter,
    target: QRectF,
    pixmap: QPixmap,
    radius: float,
) -> None:
    if pixmap.isNull():
        painter.fillRect(target, QColor("#202733"))
        return

    painter.save()
    clip = QPainterPath()
    clip.addRoundedRect(target, radius, radius)
    painter.setClipPath(clip)

    source_ratio = pixmap.width() / max(1, pixmap.height())
    target_ratio = target.width() / max(1.0, target.height())
    if source_ratio > target_ratio:
        source_height = pixmap.height()
        source_width = int(source_height * target_ratio)
        source_x = (pixmap.width() - source_width) // 2
        source = QRectF(source_x, 0, source_width, source_height)
    else:
        source_width = pixmap.width()
        source_height = int(source_width / target_ratio)
        source_y = (pixmap.height() - source_height) // 2
        source = QRectF(0, source_y, source_width, source_height)

    painter.drawPixmap(target, pixmap, source)
    painter.restore()


def _invoke_template_callback(callback: Callable[..., Any], spec: TemplateSpec) -> Any:
    """Call user/editor callbacks without forcing one rigid signature.

    Supported forms:
        callback()
        callback(template_id)
        callback(spec)                         # parameter named template/spec
        callback(template_id, spec)
    """

    try:
        signature = inspect.signature(callback)
    except (TypeError, ValueError):
        return callback(spec.template_id)

    positional = [
        parameter
        for parameter in signature.parameters.values()
        if parameter.kind
        in (inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD)
    ]
    has_varargs = any(
        parameter.kind == inspect.Parameter.VAR_POSITIONAL
        for parameter in signature.parameters.values()
    )

    if has_varargs or len(positional) >= 2:
        return callback(spec.template_id, spec)
    if not positional:
        return callback()

    parameter = positional[0]
    annotation = parameter.annotation
    wants_spec = (
        annotation is TemplateSpec
        or annotation == "TemplateSpec"
        or parameter.name.lower() in {"template", "template_spec", "spec", "descriptor"}
    )
    return callback(spec if wants_spec else spec.template_id)


def _invoke_navigation_callback(callback: Callable[..., Any], section: str) -> Any:
    try:
        signature = inspect.signature(callback)
    except (TypeError, ValueError):
        return callback(section)

    positional = [
        parameter
        for parameter in signature.parameters.values()
        if parameter.kind
        in (inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD)
    ]
    if positional:
        return callback(section)
    return callback()


# -----------------------------------------------------------------------------
# Small custom-painted controls
# -----------------------------------------------------------------------------

class FilterChip(QWidget):
    clicked = Signal(str)

    def __init__(self, key: str, text: str, width: int, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.key = key
        self.text = text
        self.checked = False
        self.hovered = False
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFixedSize(width, 40)

    def set_checked(self, checked: bool) -> None:
        if self.checked != checked:
            self.checked = checked
            self.update()

    def enterEvent(self, event: QEvent) -> None:
        self.hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event: QEvent) -> None:
        self.hovered = False
        self.update()
        super().leaveEvent(event)

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.LeftButton and self.rect().contains(event.position().toPoint()):
            self.clicked.emit(self.key)
        super().mouseReleaseEvent(event)

    def paintEvent(self, event: QEvent) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        rect = QRectF(0.75, 0.75, self.width() - 1.5, self.height() - 1.5)

        if self.checked:
            fill = QColor("#161d27")
            border = _ACCENT
            text = _ACCENT_BRIGHT
        else:
            fill = QColor("#151a20") if not self.hovered else QColor("#19212a")
            border = QColor("#303741") if not self.hovered else QColor("#3b4653")
            text = _TEXT

        painter.setPen(QPen(border, 1.25))
        painter.setBrush(fill)
        painter.drawRoundedRect(rect, 19, 19)
        painter.setPen(text)
        painter.setFont(_font(14, QFont.Weight.DemiBold if self.checked else QFont.Weight.Normal))
        painter.drawText(rect, Qt.AlignmentFlag.AlignCenter, self.text)


class BrandWidget(QWidget):
    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.collapsed = False
        self.setFixedHeight(60)

    def set_collapsed(self, collapsed: bool) -> None:
        self.collapsed = collapsed
        self.update()

    @staticmethod
    def _draw_mark(painter: QPainter, origin: QPoint) -> None:
        painter.save()
        painter.translate(origin)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        light = QColor("#67a5ff")
        blue = QColor("#4b86ed")
        dark = QColor("#3973d5")

        paths: list[tuple[QColor, list[QPoint]]] = [
            (light, [QPoint(4, 3), QPoint(17, 3), QPoint(29, 13), QPoint(22, 19), QPoint(10, 10)]),
            (blue, [QPoint(22, 19), QPoint(29, 25), QPoint(17, 36), QPoint(4, 36), QPoint(16, 25)]),
            (blue, [QPoint(25, 3), QPoint(38, 3), QPoint(49, 13), QPoint(42, 19), QPoint(31, 10)]),
            (dark, [QPoint(42, 19), QPoint(49, 25), QPoint(38, 36), QPoint(25, 36), QPoint(36, 25)]),
        ]
        painter.setPen(Qt.PenStyle.NoPen)
        for color, points in paths:
            painter.setBrush(color)
            painter.drawPolygon(QPolygon(points))
        painter.restore()

    def paintEvent(self, event: QEvent) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        x = 12 if self.collapsed else 22
        self._draw_mark(painter, QPoint(x, 10))
        if not self.collapsed:
            painter.setPen(_TEXT)
            painter.setFont(_font(24, QFont.Weight.DemiBold))
            painter.drawText(QRectF(70, 6, self.width() - 78, 48), Qt.AlignmentFlag.AlignVCenter, "SStudio")


class SidebarItem(QWidget):
    clicked = Signal(str)

    def __init__(
        self,
        section: str,
        text: str,
        icon: str,
        parent: Optional[QWidget] = None,
    ) -> None:
        super().__init__(parent)
        self.section = section
        self.text = text
        self.icon = icon
        self.selected = False
        self.hovered = False
        self.collapsed = False
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFixedHeight(54)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)

    def set_selected(self, selected: bool) -> None:
        if self.selected != selected:
            self.selected = selected
            self.update()

    def set_collapsed(self, collapsed: bool) -> None:
        self.collapsed = collapsed
        self.update()

    def enterEvent(self, event: QEvent) -> None:
        self.hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event: QEvent) -> None:
        self.hovered = False
        self.update()
        super().leaveEvent(event)

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.LeftButton and self.rect().contains(event.position().toPoint()):
            self.clicked.emit(self.section)
        super().mouseReleaseEvent(event)

    def keyPressEvent(self, event: QKeyEvent) -> None:
        if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Space):
            self.clicked.emit(self.section)
            event.accept()
            return
        super().keyPressEvent(event)

    def _draw_icon(self, painter: QPainter, center: QPoint, color: QColor) -> None:
        painter.save()
        painter.translate(center)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        pen = QPen(color, 1.8)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
        painter.setPen(pen)
        painter.setBrush(Qt.BrushStyle.NoBrush)

        if self.icon == "plus":
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(_ACCENT)
            painter.drawEllipse(QRectF(-14, -14, 28, 28))
            painter.setPen(QPen(QColor("#ffffff"), 1.8, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            painter.drawLine(-5, 0, 5, 0)
            painter.drawLine(0, -5, 0, 5)
        elif self.icon == "clock":
            painter.drawEllipse(QRectF(-11, -11, 22, 22))
            painter.drawLine(0, -6, 0, 1)
            painter.drawLine(0, 1, 5, 4)
        elif self.icon == "home":
            path = QPainterPath()
            path.moveTo(-11, -1)
            path.lineTo(0, -10)
            path.lineTo(11, -1)
            path.moveTo(-8, -3)
            path.lineTo(-8, 10)
            path.lineTo(8, 10)
            path.lineTo(8, -3)
            path.moveTo(-2, 10)
            path.lineTo(-2, 3)
            path.lineTo(3, 3)
            path.lineTo(3, 10)
            painter.drawPath(path)
        elif self.icon == "folder":
            path = QPainterPath()
            path.moveTo(-11, -8)
            path.lineTo(-3, -8)
            path.lineTo(0, -4)
            path.lineTo(11, -4)
            path.lineTo(11, 9)
            path.lineTo(-11, 9)
            path.closeSubpath()
            painter.drawPath(path)
        elif self.icon == "grid":
            for x in (-9, 2):
                for y in (-9, 2):
                    painter.drawRoundedRect(QRectF(x, y, 7, 7), 1, 1)
        elif self.icon == "archive":
            painter.drawRoundedRect(QRectF(-10, -7, 20, 16), 2, 2)
            painter.drawLine(-12, -10, 12, -10)
            painter.drawLine(-3, -2, 3, -2)
        painter.restore()

    def paintEvent(self, event: QEvent) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        if self.selected or self.hovered:
            rect = QRectF(10, 1, self.width() - 20, self.height() - 2)
            fill = QColor("#1a2941") if self.selected else QColor("#151d26")
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(fill)
            painter.drawRoundedRect(rect, 10, 10)

        icon_x = self.width() // 2 if self.collapsed else 40
        icon_color = _ACCENT_BRIGHT if self.selected else _ICON
        self._draw_icon(painter, QPoint(icon_x, self.height() // 2), icon_color)

        if not self.collapsed:
            painter.setPen(_TEXT if self.selected else _TEXT_MUTED)
            painter.setFont(_font(16, QFont.Weight.Medium if self.selected else QFont.Weight.Normal))
            painter.drawText(
                QRectF(69, 0, self.width() - 78, self.height()),
                Qt.AlignmentFlag.AlignVCenter,
                self.text,
            )


class CollapseButton(QWidget):
    clicked = Signal()

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.collapsed = False
        self.hovered = False
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFixedHeight(48)

    def set_collapsed(self, collapsed: bool) -> None:
        self.collapsed = collapsed
        self.update()

    def enterEvent(self, event: QEvent) -> None:
        self.hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event: QEvent) -> None:
        self.hovered = False
        self.update()
        super().leaveEvent(event)

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit()
        super().mouseReleaseEvent(event)

    def paintEvent(self, event: QEvent) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        icon_x = self.width() // 2 if self.collapsed else 40
        box = QRectF(icon_x - 17, 7, 34, 34)
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QColor("#171e27") if not self.hovered else QColor("#1c2631"))
        painter.drawRoundedRect(box, 7, 7)

        painter.setPen(QPen(_ICON, 1.8, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        direction = 1 if self.collapsed else -1
        for offset in (-3, 4):
            x = icon_x + offset
            painter.drawLine(x - 3 * direction, 18, x + 3 * direction, 24)
            painter.drawLine(x + 3 * direction, 24, x - 3 * direction, 30)

        if not self.collapsed:
            painter.setPen(_TEXT_MUTED)
            painter.setFont(_font(15))
            painter.drawText(QRectF(75, 0, self.width() - 82, 48), Qt.AlignmentFlag.AlignVCenter, "Hide sidebar")


class Sidebar(QWidget):
    navigation_requested = Signal(str)
    collapsed_changed = Signal(bool)

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.collapsed = False
        self.setFixedWidth(238)

        self.brand = BrandWidget(self)
        self.items: list[SidebarItem] = []
        definitions = (
            ("new_project", "New Project", "plus"),
            ("recent", "Recent", "clock"),
            ("home", "Home", "home"),
            ("projects", "Projects", "folder"),
            ("templates", "Templates", "grid"),
            ("archive", "Archive", "archive"),
        )

        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 20, 0, 17)
        layout.setSpacing(0)
        layout.addWidget(self.brand)
        layout.addSpacing(19)

        for section, text, icon in definitions:
            item = SidebarItem(section, text, icon, self)
            item.clicked.connect(self._on_item_clicked)
            item.set_selected(section == "templates")
            self.items.append(item)
            layout.addWidget(item)
            if section == "recent":
                layout.addSpacing(3)

        layout.addStretch(1)
        self.collapse_button = CollapseButton(self)
        self.collapse_button.clicked.connect(self.toggle_collapsed)
        layout.addWidget(self.collapse_button)

    def _on_item_clicked(self, section: str) -> None:
        for item in self.items:
            item.set_selected(item.section == section)
        self.navigation_requested.emit(section)

    def select_section(self, section: str) -> None:
        for item in self.items:
            item.set_selected(item.section == section)

    def toggle_collapsed(self) -> None:
        self.set_collapsed(not self.collapsed)

    def set_collapsed(self, collapsed: bool) -> None:
        if self.collapsed == collapsed:
            return
        self.collapsed = collapsed
        self.setFixedWidth(72 if collapsed else 238)
        self.brand.set_collapsed(collapsed)
        self.collapse_button.set_collapsed(collapsed)
        for item in self.items:
            item.set_collapsed(collapsed)
        self.collapsed_changed.emit(collapsed)
        self.update()

    def paintEvent(self, event: QEvent) -> None:
        painter = QPainter(self)
        gradient = QLinearGradient(0, 0, self.width(), self.height())
        gradient.setColorAt(0.0, _SIDEBAR_TOP)
        gradient.setColorAt(1.0, _SIDEBAR_BOTTOM)
        painter.fillRect(self.rect(), gradient)
        painter.setPen(QPen(_PANEL_BORDER, 1))
        painter.drawLine(self.width() - 1, 0, self.width() - 1, self.height())


class TemplateCard(QWidget):
    clicked = Signal(object)
    activated = Signal(object)

    def __init__(self, spec: TemplateSpec, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.spec = spec
        self.preview = _pixmap_from_embedded(spec.preview_key)
        self.hovered = False
        self.selected = False
        self.pressed = False
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setFixedSize(215, 294)
        self.setToolTip(spec.name)

    def set_selected(self, selected: bool) -> None:
        if self.selected != selected:
            self.selected = selected
            self.update()

    def enterEvent(self, event: QEvent) -> None:
        self.hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event: QEvent) -> None:
        self.hovered = False
        self.pressed = False
        self.update()
        super().leaveEvent(event)

    def mousePressEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            self.pressed = True
            self.update()
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            inside = self.rect().contains(event.position().toPoint())
            self.pressed = False
            self.update()
            if inside:
                self.clicked.emit(self.spec)
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            self.activated.emit(self.spec)
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def keyPressEvent(self, event: QKeyEvent) -> None:
        if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Space):
            self.activated.emit(self.spec)
            event.accept()
            return
        super().keyPressEvent(event)

    def paintEvent(self, event: QEvent) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        outer = QRectF(0.75, 0.75, self.width() - 1.5, self.height() - 1.5)
        card_gradient = QLinearGradient(0, 0, 0, self.height())
        card_gradient.setColorAt(0.0, _CARD_TOP)
        card_gradient.setColorAt(1.0, _CARD_BOTTOM)

        if self.selected:
            border = _ACCENT
            border_width = 1.5
        elif self.hovered or self.hasFocus():
            border = _CARD_BORDER_HOVER
            border_width = 1.25
        else:
            border = _CARD_BORDER
            border_width = 1.0

        painter.setPen(QPen(border, border_width))
        painter.setBrush(card_gradient)
        painter.drawRoundedRect(outer, 10, 10)

        image_rect = QRectF(7, 7, 201, 237)
        if self.pressed:
            image_rect.translate(0, 1)
        _draw_rounded_pixmap(painter, image_rect, self.preview, 8)

        painter.setPen(QColor("#2e3640"))
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.drawRoundedRect(image_rect, 8, 8)

        painter.setPen(_TEXT)
        painter.setFont(_font(16, QFont.Weight.Normal))
        painter.drawText(QRectF(13, 251, self.width() - 24, 34), Qt.AlignmentFlag.AlignVCenter, self.spec.name)


class CardsViewport(QWidget):
    card_clicked = Signal(object)
    card_activated = Signal(object)

    def __init__(self, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self._cards: list[TemplateCard] = []
        self._visible_cards: list[TemplateCard] = []
        self._last_columns = 0

        self.grid = QGridLayout(self)
        self.grid.setContentsMargins(4, 2, 4, 20)
        self.grid.setHorizontalSpacing(15)
        self.grid.setVerticalSpacing(20)
        self.grid.setAlignment(Qt.AlignmentFlag.AlignTop | Qt.AlignmentFlag.AlignLeft)

    def set_templates(self, templates: Iterable[TemplateSpec]) -> None:
        while self.grid.count():
            item = self.grid.takeAt(0)
            if item.widget() is not None:
                item.widget().deleteLater()
        self._cards.clear()

        for spec in templates:
            card = TemplateCard(spec, self)
            card.clicked.connect(self.card_clicked)
            card.activated.connect(self.card_activated)
            self._cards.append(card)
        self._visible_cards = list(self._cards)
        self._last_columns = 0
        self.reflow(force=True)

    def set_filter(self, category: str) -> None:
        for card in self._cards:
            card.setVisible(category == "all" or card.spec.category == category)
        self._visible_cards = [card for card in self._cards if not card.isHidden()]
        self._last_columns = 0
        self.reflow(force=True)

    def select(self, template_id: Optional[str]) -> None:
        for card in self._cards:
            card.set_selected(card.spec.template_id == template_id)

    def reflow(self, force: bool = False) -> None:
        available = max(215, self.width() - self.grid.contentsMargins().left() - self.grid.contentsMargins().right())
        columns = max(1, min(6, (available + 15) // 230))
        if not force and columns == self._last_columns:
            return
        self._last_columns = columns

        for index in reversed(range(self.grid.count())):
            self.grid.takeAt(index)
        for index, card in enumerate(self._visible_cards):
            row, column = divmod(index, columns)
            self.grid.addWidget(card, row, column)

        rows = max(1, (len(self._visible_cards) + columns - 1) // columns)
        self.grid.setRowStretch(rows, 1)
        minimum_height = 4 + rows * 294 + max(0, rows - 1) * 20 + 20
        self.setMinimumHeight(minimum_height)
        self.adjustSize()

    def resizeEvent(self, event: QEvent) -> None:
        self.reflow()
        super().resizeEvent(event)


class MainArea(QWidget):
    def paintEvent(self, event: QEvent) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        vertical = QLinearGradient(0, 0, 0, self.height())
        vertical.setColorAt(0.0, _BG_TOP)
        vertical.setColorAt(1.0, _BG_BOTTOM)
        painter.fillRect(self.rect(), vertical)

        glow = QRadialGradient(
            self.width() * 0.56,
            self.height() * 1.03,
            max(self.width() * 0.72, 400),
        )
        glow.setColorAt(0.0, _BG_GLOW)
        glow.setColorAt(1.0, QColor(0, 0, 0, 0))
        painter.fillRect(self.rect(), glow)


# -----------------------------------------------------------------------------
# Main embeddable page
# -----------------------------------------------------------------------------

class SStudioTemplatesPage(QWidget):
    """Embeddable template browser page.

    Signals are intentionally generic. The page does not import Ursina and does
    not depend on the editor's internal architecture.
    """

    template_selected = Signal(str)
    template_activated = Signal(str)
    template_activated_spec = Signal(object)
    navigation_requested = Signal(str)
    sidebar_collapsed = Signal(bool)

    def __init__(
        self,
        templates: Iterable[TemplateSpec] = DEFAULT_TEMPLATES,
        parent: Optional[QWidget] = None,
        *,
        activate_on_single_click: bool = False,
    ) -> None:
        super().__init__(parent)
        self.activate_on_single_click = activate_on_single_click
        self._templates: tuple[TemplateSpec, ...] = tuple(templates)
        self._template_by_id = {spec.template_id: spec for spec in self._templates}
        self._selected_template_id: Optional[str] = None
        self._filter = "all"

        root = QHBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0)
        root.setSpacing(0)

        self.sidebar = Sidebar(self)
        self.sidebar.navigation_requested.connect(self._handle_navigation)
        self.sidebar.collapsed_changed.connect(self.sidebar_collapsed)
        root.addWidget(self.sidebar)

        self.main_area = MainArea(self)
        root.addWidget(self.main_area, 1)

        content = QVBoxLayout(self.main_area)
        content.setContentsMargins(30, 29, 32, 0)
        content.setSpacing(0)

        title = QLabel("All Templates", self.main_area)
        title.setFont(_font(27, QFont.Weight.DemiBold))
        title.setStyleSheet("color: #f3f5f8; background: transparent;")
        title.setFixedHeight(42)
        content.addWidget(title)
        content.addSpacing(10)

        filter_row = QHBoxLayout()
        filter_row.setContentsMargins(0, 0, 0, 0)
        filter_row.setSpacing(14)
        self.filter_chips: dict[str, FilterChip] = {}
        for key, text, width in (
            ("all", "All", 68),
            ("blank", "Blank", 86),
            ("gameplay", "Gameplay", 116),
            ("themed", "Themed", 102),
        ):
            chip = FilterChip(key, text, width, self.main_area)
            chip.clicked.connect(self.set_filter)
            self.filter_chips[key] = chip
            filter_row.addWidget(chip)
        filter_row.addStretch(1)
        content.addLayout(filter_row)
        content.addSpacing(19)

        separator = QFrame(self.main_area)
        separator.setFixedHeight(1)
        separator.setStyleSheet("background: #252c35; border: none;")
        content.addWidget(separator)
        content.addSpacing(19)

        self.scroll = QScrollArea(self.main_area)
        self.scroll.setFrameShape(QFrame.Shape.NoFrame)
        self.scroll.setWidgetResizable(True)
        self.scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.scroll.setStyleSheet(
            "QScrollArea { background: transparent; border: none; }"
            "QScrollArea > QWidget > QWidget { background: transparent; }"
            "QScrollBar:vertical { background: transparent; width: 10px; margin: 2px; }"
            "QScrollBar::handle:vertical { background: #303945; min-height: 34px; border-radius: 4px; }"
            "QScrollBar::handle:vertical:hover { background: #3b4755; }"
            "QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; }"
            "QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }"
        )
        self.cards_viewport = CardsViewport()
        self.cards_viewport.set_templates(self._templates)
        self.cards_viewport.card_clicked.connect(self._on_card_clicked)
        self.cards_viewport.card_activated.connect(self._activate_spec)
        self.scroll.setWidget(self.cards_viewport)
        self.scroll.viewport().installEventFilter(self)
        content.addWidget(self.scroll, 1)

        self.set_filter("all")

    @property
    def templates(self) -> tuple[TemplateSpec, ...]:
        return self._templates

    @property
    def selected_template_id(self) -> Optional[str]:
        return self._selected_template_id

    def template(self, template_id: str) -> TemplateSpec:
        try:
            return self._template_by_id[template_id]
        except KeyError as error:
            raise KeyError(f"Unknown template id: {template_id!r}") from error

    def set_templates(self, templates: Iterable[TemplateSpec]) -> None:
        self._templates = tuple(templates)
        self._template_by_id = {spec.template_id: spec for spec in self._templates}
        self._selected_template_id = None
        self.cards_viewport.set_templates(self._templates)
        self.cards_viewport.set_filter(self._filter)

    def set_filter(self, category: str) -> None:
        if category not in self.filter_chips:
            raise ValueError(f"Unknown template category: {category!r}")
        self._filter = category
        for key, chip in self.filter_chips.items():
            chip.set_checked(key == category)
        self.cards_viewport.set_filter(category)

    def select_template(self, template_id: Optional[str]) -> None:
        if template_id is not None and template_id not in self._template_by_id:
            raise KeyError(f"Unknown template id: {template_id!r}")
        self._selected_template_id = template_id
        self.cards_viewport.select(template_id)
        if template_id is not None:
            self.template_selected.emit(template_id)

    def activate_template(self, template_id: str) -> None:
        self._activate_spec(self.template(template_id))

    def show_templates(self) -> None:
        self.sidebar.select_section("templates")
        self.show()
        self.raise_()

    def _on_card_clicked(self, spec: TemplateSpec) -> None:
        self.select_template(spec.template_id)
        if self.activate_on_single_click:
            self._activate_spec(spec)

    def _activate_spec(self, spec: TemplateSpec) -> None:
        self.select_template(spec.template_id)
        self.template_activated.emit(spec.template_id)
        self.template_activated_spec.emit(spec)

    def _handle_navigation(self, section: str) -> None:
        if section in {"templates", "new_project"}:
            self.sidebar.select_section("templates")
        self.navigation_requested.emit(section)

    def eventFilter(self, watched: QObject, event: QEvent) -> bool:
        if watched is self.scroll.viewport() and event.type() == QEvent.Type.Resize:
            self.cards_viewport.setMinimumWidth(max(215, self.scroll.viewport().width() - 2))
            self.cards_viewport.reflow(force=True)
        return super().eventFilter(watched, event)


# -----------------------------------------------------------------------------
# Frameless standalone window matching the reference
# -----------------------------------------------------------------------------

class WindowControl(QWidget):
    clicked = Signal()

    def __init__(self, kind: str, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.kind = kind
        self.hovered = False
        self.pressed = False
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFixedSize(46, 39)

    def enterEvent(self, event: QEvent) -> None:
        self.hovered = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event: QEvent) -> None:
        self.hovered = False
        self.pressed = False
        self.update()
        super().leaveEvent(event)

    def mousePressEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            self.pressed = True
            self.update()
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            inside = self.rect().contains(event.position().toPoint())
            self.pressed = False
            self.update()
            if inside:
                self.clicked.emit()
        super().mouseReleaseEvent(event)

    def paintEvent(self, event: QEvent) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        if self.hovered:
            painter.fillRect(self.rect(), QColor("#c42b3a") if self.kind == "close" else QColor("#1d252f"))

        color = QColor("#ffffff") if self.kind == "close" and self.hovered else _TEXT_MUTED
        painter.setPen(QPen(color, 1.35, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        cx, cy = self.width() / 2, self.height() / 2
        if self.kind == "minimize":
            painter.drawLine(int(cx - 7), int(cy + 3), int(cx + 7), int(cy + 3))
        elif self.kind == "maximize":
            painter.drawRect(QRectF(cx - 6.5, cy - 6.5, 13, 13))
        elif self.kind == "restore":
            painter.drawRect(QRectF(cx - 4.5, cy - 6.5, 11, 11))
            painter.drawLine(int(cx - 6.5), int(cy + 4.5), int(cx - 6.5), int(cy - 4.5))
            painter.drawLine(int(cx - 6.5), int(cy - 4.5), int(cx + 2.5), int(cy - 4.5))
        else:
            painter.drawLine(int(cx - 6), int(cy - 6), int(cx + 6), int(cy + 6))
            painter.drawLine(int(cx + 6), int(cy - 6), int(cx - 6), int(cy + 6))


class TopBar(QWidget):
    def __init__(self, window: "SStudioTemplatesWindow") -> None:
        super().__init__(window)
        self.window_ref = window
        self._drag_offset: Optional[QPoint] = None
        self.setFixedHeight(39)

        layout = QHBoxLayout(self)
        layout.setContentsMargins(13, 0, 0, 0)
        layout.setSpacing(0)

        for text, width in (("File", 48), ("Plugins", 72), ("Help", 54)):
            label = QLabel(text, self)
            label.setFont(_font(14))
            label.setStyleSheet("color: #c2c8d0; background: transparent;")
            label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            label.setFixedWidth(width)
            layout.addWidget(label)

        layout.addStretch(1)
        self.minimize_button = WindowControl("minimize", self)
        self.maximize_button = WindowControl("maximize", self)
        self.close_button = WindowControl("close", self)
        self.minimize_button.clicked.connect(window.showMinimized)
        self.maximize_button.clicked.connect(self._toggle_maximized)
        self.close_button.clicked.connect(window.close)
        layout.addWidget(self.minimize_button)
        layout.addWidget(self.maximize_button)
        layout.addWidget(self.close_button)

    def _toggle_maximized(self) -> None:
        if self.window_ref.isMaximized():
            self.window_ref.showNormal()
            self.maximize_button.kind = "maximize"
        else:
            self.window_ref.showMaximized()
            self.maximize_button.kind = "restore"
        self.maximize_button.update()

    def mousePressEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.LeftButton and not self.window_ref.isMaximized():
            self._drag_offset = event.globalPosition().toPoint() - self.window_ref.frameGeometry().topLeft()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event: QMouseEvent) -> None:
        if self._drag_offset is not None and event.buttons() & Qt.MouseButton.LeftButton:
            self.window_ref.move(event.globalPosition().toPoint() - self._drag_offset)
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:
        self._drag_offset = None
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event: QMouseEvent) -> None:
        if event.button() == Qt.MouseButton.LeftButton:
            self._toggle_maximized()
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def paintEvent(self, event: QEvent) -> None:
        painter = QPainter(self)
        painter.fillRect(self.rect(), _TOPBAR_BG)
        painter.setPen(QPen(_PANEL_BORDER, 1))
        painter.drawLine(0, self.height() - 1, self.width(), self.height() - 1)


class SStudioTemplatesWindow(QMainWindow):
    def __init__(
        self,
        templates: Iterable[TemplateSpec] = DEFAULT_TEMPLATES,
        *,
        activate_on_single_click: bool = False,
        parent: Optional[QWidget] = None,
    ) -> None:
        super().__init__(parent)
        self.setWindowTitle("SStudio")
        self.setWindowFlags(Qt.WindowType.Window | Qt.WindowType.FramelessWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent)
        self.resize(1672, 941)
        self.setMinimumSize(980, 650)

        shell = QWidget(self)
        shell.setStyleSheet("background: #0d1218;")
        shell_layout = QVBoxLayout(shell)
        shell_layout.setContentsMargins(0, 0, 0, 0)
        shell_layout.setSpacing(0)

        self.top_bar = TopBar(self)
        self.page = SStudioTemplatesPage(
            templates,
            self,
            activate_on_single_click=activate_on_single_click,
        )
        shell_layout.addWidget(self.top_bar)
        shell_layout.addWidget(self.page, 1)
        self.setCentralWidget(shell)


# -----------------------------------------------------------------------------
# Integration adapter
# -----------------------------------------------------------------------------

class _EditorAdapter:
    TEMPLATE_METHODS = (
        "create_project_from_template",
        "new_project_from_template",
        "open_project_template",
        "open_template",
        "load_template",
        "create_project",
    )

    NAVIGATION_METHODS: dict[str, tuple[str, ...]] = {
        "new_project": ("show_new_project", "new_project", "show_templates"),
        "recent": ("show_recent_projects", "show_recent"),
        "home": ("show_home", "show_start_page"),
        "projects": ("show_projects", "show_project_browser"),
        "templates": ("show_templates", "show_template_browser"),
        "archive": ("show_archive", "show_archived_projects"),
    }

    def __init__(
        self,
        editor: Any,
        page: SStudioTemplatesPage,
        on_template: Optional[Callable[..., Any]],
        on_navigation: Optional[Callable[..., Any]],
        template_method: Optional[str],
    ) -> None:
        self.editor = editor
        self.page = page
        self.on_template = on_template
        self.on_navigation = on_navigation
        self.template_method = template_method

    def activate_template(self, spec: TemplateSpec) -> None:
        if self.on_template is not None:
            _invoke_template_callback(self.on_template, spec)
            return

        method_names = (self.template_method,) if self.template_method else self.TEMPLATE_METHODS
        for name in method_names:
            if not name:
                continue
            method = getattr(self.editor, name, None)
            if callable(method):
                _invoke_template_callback(method, spec)
                return

        raise RuntimeError(
            "The template UI is installed, but no project-creation callback was found. "
            "Pass on_template=... to install_template_browser(), or add one of these "
            f"methods to the editor: {', '.join(self.TEMPLATE_METHODS)}."
        )

    def navigate(self, section: str) -> None:
        if section in {"templates", "new_project"}:
            return
        if self.on_navigation is not None:
            _invoke_navigation_callback(self.on_navigation, section)
            return
        for name in self.NAVIGATION_METHODS.get(section, ()): 
            method = getattr(self.editor, name, None)
            if callable(method):
                _invoke_navigation_callback(method, section)
                return


@dataclass(slots=True)
class TemplateBrowserBinding:
    """Handle returned by install_template_browser()."""

    editor: Any
    page: SStudioTemplatesPage
    stack: Optional[QStackedWidget] = None
    previous_widget: Optional[QWidget] = None

    def show(self) -> None:
        if self.stack is not None:
            self.stack.setCurrentWidget(self.page)
        self.page.show_templates()

    def show_editor(self) -> None:
        if self.stack is not None and self.previous_widget is not None:
            self.stack.setCurrentWidget(self.previous_widget)
        else:
            self.page.hide()

    def activate(self, template_id: str) -> None:
        self.page.activate_template(template_id)

    def set_templates(self, templates: Iterable[TemplateSpec]) -> None:
        self.page.set_templates(templates)


def _find_editor_stack(editor: Any) -> Optional[QStackedWidget]:
    for attribute in (
        "startup_stack",
        "start_stack",
        "page_stack",
        "stacked_widget",
        "central_stack",
        "workspace_stack",
        "main_stack",
    ):
        candidate = getattr(editor, attribute, None)
        if isinstance(candidate, QStackedWidget):
            return candidate
    if isinstance(editor, QMainWindow) and isinstance(editor.centralWidget(), QStackedWidget):
        return editor.centralWidget()
    return None


def install_template_browser(
    editor: Any,
    *,
    host: Optional[Any] = None,
    templates: Iterable[TemplateSpec] = DEFAULT_TEMPLATES,
    on_template: Optional[Callable[..., Any]] = None,
    on_navigation: Optional[Callable[..., Any]] = None,
    template_method: Optional[str] = None,
    activate_on_single_click: bool = False,
    show_immediately: bool = True,
) -> TemplateBrowserBinding:
    """Attach the page to an existing PySide6 editor with minimal glue code.

    Preferred usage:

        self.templates_ui = install_template_browser(
            self,
            on_template=self.create_project_from_template,
        )

    host can be a QStackedWidget, QMainWindow, QWidget, or QLayout. When it is
    omitted, common stack attributes are detected automatically. A QMainWindow
    with an existing central widget is wrapped in a QStackedWidget without
    discarding the original editor widget.
    """

    page = SStudioTemplatesPage(
        templates,
        activate_on_single_click=activate_on_single_click,
    )
    adapter = _EditorAdapter(editor, page, on_template, on_navigation, template_method)
    page.template_activated_spec.connect(adapter.activate_template)
    page.navigation_requested.connect(adapter.navigate)

    target = host if host is not None else _find_editor_stack(editor)
    stack: Optional[QStackedWidget] = None
    previous: Optional[QWidget] = None

    if isinstance(target, QStackedWidget):
        stack = target
        previous = stack.currentWidget()
        stack.addWidget(page)
    elif isinstance(target, QMainWindow):
        current = target.centralWidget()
        if isinstance(current, QStackedWidget):
            stack = current
            previous = stack.currentWidget()
            stack.addWidget(page)
        elif current is None:
            target.setCentralWidget(page)
        else:
            previous = target.takeCentralWidget()
            stack = QStackedWidget(target)
            stack.addWidget(previous)
            stack.addWidget(page)
            target.setCentralWidget(stack)
    elif isinstance(target, QLayout):
        target.addWidget(page)
    elif isinstance(target, QWidget):
        layout = target.layout()
        if layout is None:
            layout = QVBoxLayout(target)
            layout.setContentsMargins(0, 0, 0, 0)
            layout.setSpacing(0)
        layout.addWidget(page)
    elif isinstance(editor, QMainWindow):
        current = editor.centralWidget()
        if isinstance(current, QStackedWidget):
            stack = current
            previous = stack.currentWidget()
            stack.addWidget(page)
        elif current is None:
            editor.setCentralWidget(page)
        else:
            previous = editor.takeCentralWidget()
            stack = QStackedWidget(editor)
            stack.addWidget(previous)
            stack.addWidget(page)
            editor.setCentralWidget(stack)
    elif isinstance(editor, QWidget):
        layout = editor.layout()
        if layout is None:
            layout = QVBoxLayout(editor)
            layout.setContentsMargins(0, 0, 0, 0)
            layout.setSpacing(0)
        layout.addWidget(page)
    else:
        raise TypeError(
            "Could not determine where to attach the template browser. Pass host= with "
            "a QStackedWidget, QMainWindow, QWidget, or QLayout."
        )

    binding = TemplateBrowserBinding(editor, page, stack, previous)
    if show_immediately:
        binding.show()
    return binding


# -----------------------------------------------------------------------------
# Standalone demo
# -----------------------------------------------------------------------------

def _demo_template_handler(template_id: str, spec: TemplateSpec) -> None:
    print(f"Create project from template: {template_id} ({spec.name})")


def main() -> int:
    app = QApplication.instance() or QApplication(sys.argv)
    app.setApplicationName("SStudio")
    app.setStyle("Fusion")

    window = SStudioTemplatesWindow()
    window.page.template_activated_spec.connect(
        lambda spec: _demo_template_handler(spec.template_id, spec)
    )
    window.show()
    return app.exec()


if __name__ == "__main__":
    raise SystemExit(main())
